#!/usr/bin/env node
/**
 * TRED — le signalement cote web, et sa lecture cote admin.
 *
 * Lancable depuis n'importe ou dans le depot :
 *     node <chemin>\tred-signalement-web.mjs
 *
 * Ce que ca ajoute :
 *
 *   1. Un drapeau "Melden" sous chaque reponse du tuteur sur le SITE, comme
 *      dans l'app. Google ne l'exige que dans l'app, mais la regle vise une
 *      chose reelle : le web sert le meme modele.
 *
 *   2. Une section "Gemeldete Antworten" EN TETE de la page d'administration.
 *      Sans elle, le bouton exige par Google serait une boite aux lettres
 *      sans cle : conforme, et parfaitement inutile.
 *
 *   3. Les routes /api/admin/reports (liste) et /api/admin/reports/resolve.
 *      Elles remplacent reports.listOpen et reports.resolve cote oRPC : deux
 *      chemins pour la meme chose finissent toujours par diverger sur la
 *      verification du role. La garde requireAdmin() est ecrite une fois.
 *
 *   4. Les textes juridiques completes (memes octets que corrige-legal.mjs,
 *      donc sans effet si tu l'as deja lance).
 */
import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = depart;
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const p = dirname(d);
      if (p === d) break;
      d = p;
    }
  }
  return null;
}

const ROOT = racine();
if (!ROOT) {
  console.error("\n  x  Depot introuvable en remontant depuis le script.\n");
  process.exit(1);
}

const FILES = {
"packages/web/src/api/index.ts": "",
"packages/web/src/api/routes/reports.ts": "",
"packages/web/src/api/database/schema.ts": "",
"packages/web/src/api/lib/gdpr.ts": "",
"packages/web/src/web/pages/admin.tsx": "",
"packages/web/src/web/pages/chat.tsx": "",
"packages/web/src/web/components/report-answer.tsx": "",
"packages/web/src/web/data/legal.ts": "",
"packages/web/src/web/i18n/messages/de.ts": "",
"packages/web/src/web/i18n/messages/en.ts": "",
"packages/web/src/web/i18n/messages/fr.ts": "",
"packages/web/src/web/i18n/messages/es.ts": ""
};
for (const [rel, b64] of Object.entries(FILES)) {
  const cible = join(ROOT, rel);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  console.log("  ecrit  " + rel);
}

console.log(`
  Aucune migration : la table content_report suffit.

  Pour voir la section, il faut etre admin — le role vient de ADMIN_EMAILS
  dans les variables Railway, et il est relu a chaque appel.

  La section n'apparait QUE s'il y a des signalements ouverts. Une page
  d'admin qui affiche un cadre vide en permanence apprend a l'ignorer.
`);
